    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Output indices with register blocking
    int row = blockIdx.y * TILE_SIZE + ty * REG_BLOCK;
    int col = blockIdx.x * TILE_SIZE + tx * REG_BLOCK;

    // Register accumulators
    float c[REG_BLOCK][REG_BLOCK] = {{0.0f}};

    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tile of A into shared memory
        int load_row = blockIdx.y * TILE_SIZE + ty;
        int load_col = tile * TILE_SIZE + tx;
        if (load_row < N && load_col < N) {
            As[ty][tx] = A[load_row * N + load_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory
